xhtml:body.xhtml:script:
//
  (function() {
    function size() {
      var w = window.innerWidth, h = window.innerHeight;
      var svg = document.querySelector('svg');
      var fo  = document.querySelector('foreignObject');
      if (svg) { svg.setAttribute('width', w); svg.setAttribute('height', h); svg.setAttribute('viewBox','0 0 '+w+' '+h); }
      if (fo)  { fo.setAttribute('width', w);  fo.setAttribute('height', h); }
    }
    size();
    window.addEventListener('resize', size);

    (async function() {
      try {
        var cdnRoot = 'https://cdn.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.1/';
        var cdnCandidates = [
          cdnRoot,
          'https://fastly.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.1/',
          'https://gcore.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.1/',
          'https://originfastly.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.1/',
          'https://jsdelivr.b-cdn.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.1/'
        ];

        var text = '';
        var activeCdn = cdnRoot;
        for (var i = 0; i < cdnCandidates.length; i++) {
          try {
            var res = await fetch(cdnCandidates[i] + 'index.html?t=' + Date.now());
            if (res.ok) {
              text = await res.text();
              activeCdn = cdnCandidates[i];
              break;
            }
          } catch(e) {}
        }

        if (!text) {
          var fallback = await fetch(cdnRoot + 'index.html');
          text = await fallback.text();
        }

        var baseTag = '<base href="' + activeCdn + '">';
        if (text.includes('<head>')) {
          text = text.replace('<head>', '<head>' + baseTag);
        } else {
          text = baseTag + text;
        }

        var frame = document.getElementById('fm');
        var fdoc = frame.contentDocument || frame.contentWindow.document;
        fdoc.open();
        fdoc.write(text);
        fdoc.close();
      } catch(err) {
        console.error('PeteZah Loader Error:', err);
      }
    })();
  })();
//
